import React from 'react';

const MovieCard = ({ movie }) => {
    return (
        <div style={{
            border: '1px solid #e0e0e0',
            borderRadius: '16px',
            padding: '30px',
            textAlign: 'center',
            backgroundColor: '#ffffff',
            boxShadow: '0 8px 16px rgba(0,0,0,0.1)',
            transition: 'transform 0.2s',
            maxWidth: '500px',
            margin: '0 auto'
        }}>
            {/* Film İsmi */}
            <h2 style={{ color: '#2c3e50', fontSize: '28px', margin: '0 0 10px 0' }}>
                {movie.recommendedMovieTitle}
            </h2>

            {/* API'den gelen mesaj (Örn: Algoritma çalıştı...) */}
            <p style={{ fontStyle: 'italic', color: '#3498db', fontSize: '16px' }}>
                "{movie.message}"
            </p>

            {/* TMDB ID'si (Küçük bir detay olarak köşede durabilir) */}
            <span style={{
                display: 'inline-block',
                marginTop: '15px',
                padding: '5px 10px',
                backgroundColor: '#f1f2f6',
                color: '#a4b0be',
                borderRadius: '8px',
                fontSize: '12px'
            }}>
                TMDB ID: {movie.recommendedMovieId}
            </span>
        </div>
    );
};

export default MovieCard;
